<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { FileText, Users, MessageSquare, ArrowUpRight, Plus, Search, X, Check, Clock3, AlertCircle, Activity, Upload, Eye, Ban, Pencil, ExternalLink, RefreshCw } from 'lucide-vue-next'
import { api } from './api'
import Markdown from './Markdown.vue'
import { suggestCode, versionsFor, suggestVersion } from './documentHints'
const props = defineProps({ page: String })
const overview = ref(null), docs = ref([]), users = ref([]), runs = ref([]), search = ref(''), status = ref(''), error = ref(''), notice = ref(''), busy = ref(false), loading = ref(false), dialog = ref(''), preview = ref(null), selectedRun = ref(null), editingUser = ref(null), file = ref(null), editingDoc = ref(null), replacePrevious = ref(false)
const docForm = ref({}), userForm = ref({})
const categoryDoc = ref(null), categoryValue = ref('业务流程')
const docMode = ref('new'), existingCode = ref('')
const codePrefixes = ['FLOW', 'BIZ', 'HR', 'JOB', 'AUTH', 'ORG', 'KNOW']
const codePrefix = ref('FLOW')
const codeSuggestion = computed(() => suggestCode(docs.value, codePrefix.value))
const codeGroups = computed(() => [...new Set(docs.value.map(d => d.code))].sort().map(code => versionsFor(docs.value, code)[0]))
const knownVersions = computed(() => versionsFor(docs.value, docForm.value.code || ''))
const versionSuggestion = computed(() => suggestVersion(docs.value, docForm.value.code || ''))
const duplicateVersion = computed(() => knownVersions.value.some(d => d.version === (docForm.value.version || '').trim() && d.id !== editingDoc.value))
const docConflict = computed(() => duplicateVersion.value ? '该编号与版本已存在，请修改版本号或编辑已有草稿。' : !editingDoc.value && docMode.value === 'new' && knownVersions.value.length ? '该编号已使用，请切换到“已有文档的新版本”。' : '')
const pageTitles = { overview: ['工作台概览', '让知识有序，让协作更顺畅。'], documents: ['知识文档', '从一份可靠的文档，开始一个有依据的回答。'], users: ['员工管理', '维护账号与岗位资料，为每次问答提供适用条件。'], runs: ['问答与反馈', '看见每一次检索，也看见需要改进的地方。'] }
const title = computed(() => pageTitles[props.page] || pageTitles.overview)
const filteredDocs = computed(() => docs.value.filter(d => `${d.title} ${d.code}`.toLowerCase().includes(search.value.toLowerCase()) && (!status.value || d.status === status.value)))
const filteredRuns = computed(() => runs.value.filter(r => `${r.question} ${r.user_name}`.includes(search.value) && (!status.value || r.status === status.value)))
const statusText = s => ({ published: '已发布', draft: '待发布', disabled: '已停用', completed: '已完成', failed: '执行失败', running: '执行中', pending: '待执行', cancelled: '已放弃' }[s] || s)
async function load() { loading.value = true; error.value = ''; try { [overview.value, docs.value, users.value, runs.value] = await Promise.all([api('/admin/overview'), api('/documents'), api('/admin/users'), api('/admin/runs')]) } catch (e) { error.value = e.message } finally { loading.value = false } }
watch(() => props.page, () => { search.value = ''; status.value = ''; notice.value = ''; load() })
onMounted(load)
async function action(fn, success) { busy.value = true; error.value = ''; try { await fn(); notice.value = success; await load(); return true } catch (e) { error.value = e.message; return false } finally { busy.value = false } }
async function viewDoc(d) { try { preview.value = await api(`/documents/${d.id}`); replacePrevious.value = false; dialog.value = 'preview' } catch (e) { error.value = e.message } }
function newDoc() { editingDoc.value = null; file.value = null; docMode.value = 'new'; existingCode.value = ''; docForm.value = { code: suggestCode(docs.value, codePrefix.value), title: '', version: '1.0', category: '业务流程', effective_from: new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' }), effective_to: '', content: '' }; dialog.value = 'document' }
function switchDocMode() { docForm.value.code = docMode.value === 'new' ? codeSuggestion.value : ''; docForm.value.version = '1.0'; existingCode.value = '' }
function useExisting(code) { existingCode.value = code; const latest = versionsFor(docs.value, code)[0]; if (!latest) return; docForm.value.code = code; docForm.value.title = latest.title; docForm.value.category = latest.category; docForm.value.version = suggestVersion(docs.value, code) }
function newVersion(d) { newDoc(); docMode.value = 'version'; useExisting(d.code) }
function editDraft() { editingDoc.value = preview.value.id; file.value = null; docForm.value = { ...preview.value, effective_to: preview.value.effective_to || '' }; dialog.value = 'document' }
async function publishPreview() { const d = preview.value; const ok = await action(() => api(`/admin/documents/${d.id}/publish?replace_previous=${replacePrevious.value}`, { method: 'POST' }), '版本已发布'); if (ok) await viewDoc(d) }
function editCategory(d) { categoryDoc.value = d; categoryValue.value = d.category; error.value = ''; dialog.value = 'category' }
async function saveCategory() { const ok = await action(() => api(`/admin/documents/${categoryDoc.value.id}/category`, { method: 'PATCH', body: { category: categoryValue.value } }), '文档分类已更新'); if (ok) dialog.value = '' }
async function saveDoc() {
  if (docConflict.value) { error.value = docConflict.value; return }
  if (!editingDoc.value && docMode.value === 'version' && !existingCode.value) { error.value = '请先选择已有文档'; return }
  docForm.value.code = docForm.value.code.trim().toUpperCase(); docForm.value.version = docForm.value.version.trim()
  const success = await action(async () => {
    if (file.value) { const form = new FormData(); for (const [k, v] of Object.entries(docForm.value)) if (k !== 'content') form.append(k, v); form.append('file', file.value); await api('/admin/documents/upload', { method: 'POST', body: form }) }
    else await api(editingDoc.value ? `/admin/documents/${editingDoc.value}` : '/admin/documents', { method: editingDoc.value ? 'PUT' : 'POST', body: { ...docForm.value, effective_to: docForm.value.effective_to || null } })
  }, '文档已解析为草稿，请预览后发布')
  if (success) dialog.value = ''
}
function editUser(u = null) { editingUser.value = u; userForm.value = u ? { ...u, password: '' } : { username: '', name: '', password: '', department: '运营部', position: '店铺运营专员', hire_date: '2026-10-01', probation: true, active: true, feishu_open_id: '' }; dialog.value = 'user' }
async function saveUser() { const ok = await action(() => api(editingUser.value ? `/admin/users/${editingUser.value.id}` : '/admin/users', { method: editingUser.value ? 'PUT' : 'POST', body: userForm.value }), '员工资料已保存'); if (ok) dialog.value = '' }
function fileChange(e) { file.value = e.target.files[0] || null; if (file.value && !docForm.value.title) docForm.value.title = file.value.name.replace(/\.[^.]+$/, '') }
function close(e) { if (!busy.value && (!e || e.target === e.currentTarget)) dialog.value = '' }
function modalKey(e) { if (e.key === 'Escape') close(); if (e.key === 'Tab') { const nodes = [...e.currentTarget.querySelectorAll('button,input,textarea,select,a')].filter(n => !n.disabled); if (e.shiftKey && document.activeElement === nodes[0]) { e.preventDefault(); nodes.at(-1)?.focus() } else if (!e.shiftKey && document.activeElement === nodes.at(-1)) { e.preventDefault(); nodes[0]?.focus() } } }
const vAutofocus = { mounted: el => setTimeout(() => el.focus(), 0) }
</script>
<template>
  <section class="admin-page">
    <header class="page-header"><div><span class="eyebrow">KNOWLEDGE OPERATIONS</span><h1>{{ title[0] }}</h1><p>{{ title[1] }}</p></div><button v-if="page === 'documents'" class="button primary" @click="newDoc"><Plus :size="17"/>添加文档</button><button v-else-if="page === 'users'" class="button primary" @click="editUser()"><Plus :size="17"/>创建员工</button><button v-else class="button outline compact" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{ spin: loading }"/>刷新</button></header>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status"><Check :size="16"/>{{ notice }}</p>
    <template v-if="page === 'overview' && overview">
      <div class="admin-welcome"><div><span class="eyebrow">THE BIG PICTURE</span><h2>把散落的知识，<br/>变成新同事的底气。</h2><p>维护可信的知识来源，让每一次业务问答都有迹可循。</p><button class="button light" @click="$emit('navigate', 'documents')">管理知识文档<ArrowUpRight :size="17"/></button></div><div class="orbit-art" aria-hidden="true"><div class="orbit-circle one"></div><div class="orbit-circle two"></div><div class="art-file a"><FileText :size="36" :stroke-width="1"/></div><div class="art-file b"><FileText :size="30" :stroke-width="1"/></div><div class="art-dot"></div><span>KNOWLEDGE<br/>IN MOTION.</span></div></div>
      <div class="stat-grid"><div class="stat-card" v-for="s in [{ label: '已发布文档版本', value: overview.published, icon: FileText, note: '为问答提供可信依据' }, { label: '员工与管理员', value: overview.employees, icon: Users, note: '账号资料辅助条件判断' }, { label: '累计提问', value: overview.questions, icon: MessageSquare, note: `${overview.completed} 次已完成` }, { label: '收到反馈', value: overview.feedback, icon: Activity, note: '帮助持续改进知识服务' }]" :key="s.label"><div><span>{{ s.label }}</span><component :is="s.icon" :size="18"/></div><strong>{{ s.value }}<small>项</small></strong><p>{{ s.note }}</p></div></div>
      <div class="overview-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">RECENT ACTIVITY</span><h3>最近问答</h3></div><button class="text-button" @click="$emit('navigate', 'runs')">查看全部<ArrowUpRight :size="14"/></button></div><div v-if="!runs.length" class="empty-state"><MessageSquare :size="28"/><strong>等待第一个好问题</strong><p>从左侧进入知识助手，开始一次业务问答。</p></div><button v-for="r in runs.slice(0, 4)" :key="r.id" class="recent-run" @click="selectedRun = r; dialog = 'run'"><div><strong>{{ r.question }}</strong><span>{{ r.user_name }} · {{ r.created_at.slice(0, 10) }}</span></div><span class="status" :class="r.status">{{ statusText(r.status) }}</span></button></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">SERVICE STATUS</span><h3>服务配置</h3></div><span class="pill">{{ overview.mode === 'demo' ? '演示模式' : 'API 模式' }}</span></div><div class="service-row" v-for="[key, label] in [['generation', 'DeepSeek 生成服务'], ['embedding', 'Embedding API'], ['rerank_local', 'BGE 本地重排模型'], ['langsmith', 'LangSmith 追踪'], ['feishu', '飞书机器人']]" :key="key"><span>{{ label }}</span><span class="status" :class="overview.configured[key] ? 'published' : 'draft'">{{ overview.configured[key] ? '已配置' : '待配置' }}</span></div><p class="panel-footnote">这里显示配置状态，不代表外部服务连通性已验证。知识库代次 {{ overview.revision }}。</p></section></div>
    </template>
    <template v-if="page === 'documents'">
      <div class="table-toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" aria-label="搜索文档" placeholder="搜索文档名称或编号…"/></div><select v-model="status" aria-label="筛选文档状态"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">待发布</option><option value="disabled">已停用</option></select><span class="muted">{{ filteredDocs.length }} 个版本</span></div>
      <div class="table-wrap document-table scroll-table" tabindex="0" role="region" aria-label="知识文档列表"><table><thead><tr><th>文档名称</th><th>分类</th><th>版本</th><th>适用日期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in filteredDocs" :key="d.id"><td><div class="document-name"><span class="mini-file"><FileText :size="18"/></span><div><strong>{{ d.title }}</strong><small>{{ d.code }}</small></div></div></td><td><button class="text-button category-edit" :aria-label="`修改分类：${d.title}`" title="修改分类" @click="editCategory(d)">{{ d.category }}<Pencil :size="12"/></button></td><td><span class="version">v{{ d.version }}</span></td><td class="date-cell">{{ d.effective_from }}<small>{{ d.effective_to ? `至 ${d.effective_to}（不含）` : '持续有效' }}</small></td><td><span class="status" :class="d.status">{{ statusText(d.status) }}</span></td><td><div class="table-actions"><button class="text-button" :disabled="busy" @click="newVersion(d)">新版本</button><button class="icon-button" :aria-label="`预览${d.title}`" title="预览文档" @click="viewDoc(d)"><Eye :size="17"/></button><button v-if="d.status !== 'published'" class="text-button" :disabled="busy" @click="action(() => api(`/admin/documents/${d.id}/publish`, { method: 'POST' }), '文档已发布')">发布</button><button v-else class="icon-button" :disabled="busy" :aria-label="`停用${d.title}`" title="停用文档" @click="action(() => api(`/admin/documents/${d.id}/disable`, { method: 'POST' }), '文档已停用；历史引用仍可核对')"><Ban :size="16"/></button></div></td></tr></tbody></table><div v-if="!filteredDocs.length" class="empty-state"><FileText :size="26"/><strong>没有匹配的文档</strong><p>调整筛选条件，或添加第一份文档。</p></div></div><div class="info-note"><AlertCircle :size="16"/>发布前请核对解析内容及有效期；同一制度的有效期不能重叠。已发布版本保留原文，请通过新版本更新制度。</div>
    </template>
    <template v-if="page === 'users'"><div class="employee-grid"><article v-for="u in users" :key="u.id" class="employee-card"><div class="row-between"><div class="avatar" :class="{ muted: !u.active }">{{ u.name[0] }}</div><span class="status" :class="u.active ? 'published' : 'disabled'">{{ u.active ? '使用中' : '已停用' }}</span></div><h3>{{ u.name }}</h3><p>{{ u.department }} · {{ u.position }}</p><dl><div><dt>登录账号</dt><dd>{{ u.username }}</dd></div><div><dt>员工状态</dt><dd>{{ u.role === 'admin' ? '管理员' : u.probation ? '试用期' : '正式员工' }}</dd></div><div><dt>入职日期</dt><dd>{{ u.hire_date }}</dd></div><div><dt>飞书身份</dt><dd>{{ u.feishu_open_id ? '已绑定' : '未绑定' }}</dd></div></dl><button v-if="u.role !== 'admin'" class="button outline full" @click="editUser(u)"><Pencil :size="15"/>编辑员工资料</button><span v-else class="admin-account-note">系统管理员账号</span></article></div></template>
    <template v-if="page === 'runs'"><div class="table-toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" aria-label="搜索问答" placeholder="搜索问题或员工…"/></div><select v-model="status" aria-label="筛选执行状态"><option value="">全部状态</option><option value="completed">已完成</option><option value="failed">执行失败</option><option value="running">执行中</option></select></div><div class="table-wrap runs-table scroll-table" tabindex="0" role="region" aria-label="问答与反馈列表"><table><thead><tr><th>问题</th><th>员工</th><th>状态</th><th>耗时</th><th>反馈</th><th>详情</th></tr></thead><tbody><tr v-for="r in filteredRuns" :key="r.id"><td class="question-cell"><strong>{{ r.question }}</strong><small>{{ r.created_at.replace('T', ' ').slice(0, 19) }} UTC</small></td><td>{{ r.user_name }}</td><td><span class="status" :class="r.status">{{ statusText(r.status) }}</span></td><td>{{ (r.elapsed_ms / 1000).toFixed(1) }}s</td><td>{{ r.feedback ? r.feedback.helpful ? '有帮助' : '待改进' : '—' }}</td><td><button class="icon-button" aria-label="查看运行详情" @click="selectedRun = r; dialog = 'run'"><ArrowUpRight :size="18"/></button></td></tr></tbody></table><div v-if="!filteredRuns.length" class="empty-state"><MessageSquare :size="26"/><strong>还没有匹配的问答</strong><p>员工提交问题后，可以在这里查看执行与反馈。</p></div></div></template>
    <div v-if="loading && !overview" class="empty-state" role="status">正在加载工作台…</div>
    <div v-if="dialog" class="modal-backdrop" @click="close" @keydown="modalKey"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><h2 id="modal-title">{{ ({ document: '添加知识文档', category: '修改文档分类', user: editingUser ? '编辑员工资料' : '创建员工账号', preview: '文档原文与解析预览', run: '问答运行详情' })[dialog] }}</h2><button v-autofocus class="icon-button" aria-label="关闭窗口" :disabled="busy" @click="close()"><X :size="20"/></button></header><p v-if="error" class="error" role="alert">{{ error }}</p>
      <form v-if="dialog === 'document'" class="form-grid" @submit.prevent="saveDoc">
        <div v-if="!editingDoc" class="document-mode span-2">
          <label>录入类型<select v-model="docMode" @change="switchDocMode"><option value="new">全新文档</option><option value="version">已有文档的新版本</option></select></label>
          <label v-if="docMode === 'new'">编号前缀<select v-model="codePrefix" @change="docForm.code = codeSuggestion"><option v-for="prefix in codePrefixes" :key="prefix">{{ prefix }}</option></select></label>
          <label v-else>选择已有文档<select v-model="existingCode" required @change="useExisting(existingCode)"><option disabled value="">请选择文档</option><option v-for="d in codeGroups" :key="d.code" :value="d.code">{{ d.code }} · {{ d.title }}</option></select></label>
          <p class="muted span-2">{{ docMode === 'new' ? '按所选前缀的最大已用序号推荐，可手动修改；保存时校验是否重复。' : '沿用原编号、名称与分类，上传或填写新版正文。' }}</p>
        </div>
<label class="span-2">文档名称<input v-model="docForm.title" required maxlength="200" placeholder="例如：客户需求变更处理规范"/></label><label>文档编号<input aria-label="文档编号" v-model="docForm.code" :readonly="!editingDoc && docMode === 'version'" required pattern="[A-Z]+-[0-9]{3}" placeholder="例如 FLOW-008" @input="docForm.code = docForm.code.toUpperCase()"/><small v-if="!editingDoc && docMode === 'new'" class="field-hint">{{ codeSuggestion ? `当前建议：${codeSuggestion}` : '此前缀已用满，请选择其他前缀。' }}</small></label>
        <label>版本号<input aria-label="版本号" v-model="docForm.version" required maxlength="30" placeholder="例如 1.0" :aria-invalid="duplicateVersion"/><small class="field-hint">{{ versionSuggestion ? `建议 v${versionSuggestion}（可修改）` : '已有非数字版本，请按实际命名规则填写。' }}</small></label>
        <p v-if="docConflict" class="field-error span-2" role="alert">{{ docConflict }}</p>
        <section v-if="knownVersions.length" class="version-history span-2" aria-label="已有版本记录"><strong>{{ docForm.code }} 的已有版本 · {{ knownVersions.length }} 条</strong><p class="muted">数字版本按版本号排序；包含草稿与停用版本。下一版本默认递增主版本号。</p><div class="version-history-list"><div v-for="d in knownVersions" :key="d.id"><span>v{{ d.version }}</span><span class="status" :class="d.status">{{ statusText(d.status) }}</span><span>{{ d.effective_from }} 至 {{ d.effective_to || '未设结束日期' }}</span></div></div></section><label>生效日期<input v-model="docForm.effective_from" type="date" required/></label><label>失效日期（不含，可留空）<input v-model="docForm.effective_to" type="date"/></label><label class="span-2">文档分类<select v-model="docForm.category"><option>业务流程</option><option>公司业务</option><option>岗位职责</option><option>入职制度</option><option>经营知识</option></select></label><label v-if="!editingDoc" class="upload-zone span-2"><Upload :size="23"/><strong>{{ file ? file.name : '选择文档文件' }}</strong><span>Markdown / TXT / DOCX / 文字型 PDF，最大 10 MB</span><input type="file" accept=".md,.txt,.docx,.pdf" @change="fileChange"/></label><label v-if="!file" class="span-2">或直接填写 Markdown 内容<textarea v-model="docForm.content" rows="7" required placeholder="## 适用范围&#10;在这里编写完整条款、条件和例外说明…"/></label><div class="modal-actions span-2"><span class="muted">保存后为草稿，预览后再发布</span><button class="button primary" :disabled="busy || !!docConflict || (!editingDoc && docMode === 'version' && !existingCode)">{{ busy ? '解析与保存中…' : '保存并解析' }}</button></div></form>
      <form v-if="dialog === 'user'" class="form-grid" @submit.prevent="saveUser"><label>登录账号<input v-model="userForm.username" required pattern="[a-zA-Z0-9_.-]+"/></label><label>姓名<input v-model="userForm.name" required/></label><label class="span-2">{{ editingUser ? '新密码（留空不修改）' : '初始密码（至少8位）' }}<input v-model="userForm.password" type="password" :required="!editingUser" :minlength="8" autocomplete="new-password"/></label><label>部门<input v-model="userForm.department" required/></label><label>岗位<input v-model="userForm.position" required/></label><label>入职日期<input v-model="userForm.hire_date" type="date" required/></label><label>员工状态<select v-model="userForm.probation"><option :value="true">试用期</option><option :value="false">正式员工</option></select></label><label class="span-2">飞书 Open ID（选填）<input v-model="userForm.feishu_open_id" placeholder="用于将飞书用户映射到员工账号"/></label><label class="checkbox-label span-2"><input v-model="userForm.active" type="checkbox"/>允许该账号登录</label><div class="modal-actions span-2"><span></span><button class="button primary" :disabled="busy">{{ busy ? '保存中…' : '保存员工资料' }}</button></div></form>
      <template v-if="dialog === 'preview' && preview"><div class="preview-meta"><span class="pill">{{ preview.code }}</span><span>v{{ preview.version }} · {{ preview.effective_from }} 起生效</span><span class="status" :class="preview.status">{{ statusText(preview.status) }}</span></div><div v-if="preview.status === 'draft'" class="publish-controls"><label class="checkbox-label"><input v-model="replacePrevious" type="checkbox"/>替换发布：在新版生效日关闭旧版本的有效期</label><div><button class="button outline compact" :disabled="busy" @click="editDraft">编辑草稿</button><button class="button primary compact" :disabled="busy" @click="publishPreview">{{ busy ? '正在索引…' : '确认并发布' }}</button></div></div><Markdown :text="preview.content"/><details class="chunk-preview"><summary>查看解析结果 · {{ preview.chunks.length }} 个片段</summary><article v-for="c in preview.chunks" :key="c.id"><strong>{{ c.section }}</strong><p>{{ c.text }}</p><small>{{ c.location }} · 引用 {{ c.refs.join('、') || '无' }}</small></article></details></template>
      <template v-if="dialog === 'run' && selectedRun"><div class="run-summary"><span class="status" :class="selectedRun.status">{{ statusText(selectedRun.status) }}</span><span>{{ selectedRun.elapsed_ms }} ms</span><span>知识库代次 {{ selectedRun.revision }}</span></div><h3>{{ selectedRun.question }}</h3><p v-if="selectedRun.error" class="error">{{ selectedRun.error }}</p><Markdown v-if="selectedRun.result?.answer" :text="selectedRun.result.answer" hide-citations/><div v-if="selectedRun.feedback" class="info-note">员工反馈：{{ selectedRun.feedback.helpful ? '有帮助' : '无帮助' }} {{ selectedRun.feedback.reason }}</div><h3>执行节点</h3><ol class="event-list"><li v-for="(e, i) in selectedRun.events" :key="i"><strong>{{ e.stage }}</strong><pre>{{ typeof e.detail === 'string' ? e.detail : JSON.stringify(e.detail, null, 2) }}</pre></li></ol><a v-if="selectedRun.trace_url" :href="selectedRun.trace_url" target="_blank" rel="noopener noreferrer" class="button primary">在 LangSmith 查看<ExternalLink :size="16"/></a><p v-else class="muted">此请求没有可用的 LangSmith 追踪链接。</p></template>
      <details v-if="dialog === 'run' && selectedRun" class="chunk-preview"><summary>模型调用与用量 · {{ selectedRun.metrics?.length || 0 }} 次</summary><p v-if="!selectedRun.metrics?.length">此请求没有真实 API 用量记录。</p><article v-for="(m, i) in selectedRun.metrics || []" :key="i"><strong>{{ m.model }} · {{ m.endpoint }}</strong><p>{{ m.status }} · {{ m.elapsed_ms }} ms</p><pre>{{ JSON.stringify(m.usage || {}, null, 2) }}</pre></article></details>
      <form v-if="dialog === 'category' && categoryDoc" class="form-grid" @submit.prevent="saveCategory">
        <div class="span-2"><h3>{{ categoryDoc.title }}</h3><p class="muted">{{ categoryDoc.code }} · v{{ categoryDoc.version }}</p></div>
        <label class="span-2">文档分类<select v-model="categoryValue" required><option>业务流程</option><option>公司业务</option><option>岗位职责</option><option>入职制度</option><option>经营知识</option></select></label>
        <div class="modal-actions span-2"><span class="muted">仅更新当前文档版本的分类</span><button class="button primary" :disabled="busy">{{ busy ? '保存中…' : '保存分类' }}</button></div>
      </form>
    </section></div>
  </section>
</template>
